#!/usr/bin/env python3

import sys

import cv2
import numpy as np


def read_frames(path):
    cap = cv2.VideoCapture(path)
    if not cap.isOpened():
        raise ValueError("could not open video: %s" % path)
    frames = []
    while True:
        ok, frame = cap.read()
        if not ok:
            break
        frames.append(cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY))
    cap.release()
    if not frames:
        raise ValueError("video contains no frames: %s" % path)
    return frames


def foreground_boxes(frames):
    height, width = frames[0].shape
    subtractor = cv2.createBackgroundSubtractorMOG2(
        history=60, varThreshold=16, detectShadows=False
    )
    for _ in range(3):
        subtractor.apply(frames[0], learningRate=1.0)

    open_kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))
    dilate_kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (15, 15))
    boxes = []

    for frame in frames:
        mask = subtractor.apply(frame)
        _, mask = cv2.threshold(mask, 127, 255, cv2.THRESH_BINARY)
        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, open_kernel)
        mask = cv2.dilate(mask, dilate_kernel, iterations=1)

        count, labels, stats, centroids = cv2.connectedComponentsWithStats(
            mask, 8
        )
        if count <= 1:
            boxes.append(None)
            continue

        index = 1 + int(
            np.argmax(stats[1:, cv2.CC_STAT_AREA])
        )
        x = int(stats[index, cv2.CC_STAT_LEFT])
        y = int(stats[index, cv2.CC_STAT_TOP])
        w = int(stats[index, cv2.CC_STAT_WIDTH])
        h = int(stats[index, cv2.CC_STAT_HEIGHT])
        area = int(stats[index, cv2.CC_STAT_AREA])
        cx = float(centroids[index][0])
        boxes.append(
            {
                "area": area,
                "x": x,
                "y": y,
                "w": w,
                "h": h,
                "bottom": y + h,
                "cx": cx,
            }
        )

    return boxes, width, height


def is_athlete(box, width, height):
    if box is None:
        return False
    min_area = max(1500, int(0.008 * width * height))
    min_height = max(60, int(0.22 * height))
    return (
        box["area"] >= min_area
        and box["h"] >= min_height
        and box["w"] <= 0.9 * width
        and box["h"] >= 0.45 * box["w"]
    )


def find_run(boxes, width, height):
    indices = [i for i, b in enumerate(boxes) if is_athlete(b, width, height)]
    if not indices:
        return None

    runs = []
    current = [indices[0]]
    for index in indices[1:]:
        if index - current[-1] <= 3:
            current.append(index)
        else:
            runs.append(current)
            current = [index]
    runs.append(current)

    best = None
    best_score = None
    for run in runs:
        displacement = abs(boxes[run[-1]]["cx"] - boxes[run[0]]["cx"])
        score = (displacement, len(run))
        if best_score is None or score > best_score:
            best_score = score
            best = run
    return best


def estimate_jump(frames):
    boxes, width, height = foreground_boxes(frames)
    run = find_run(boxes, width, height)
    if run is None or len(run) < 3:
        return 0, max(0, len(frames) - 1)

    frame_numbers = np.array(run, dtype=float)
    bottoms = np.array([boxes[i]["bottom"] for i in run], dtype=float)
    baseline = float(np.percentile(bottoms, 75))
    margin = max(10.0, 0.03 * height)
    threshold = baseline - margin

    apex = int(np.argmin(bottoms))
    below = bottoms < threshold

    left = apex
    while left > 0 and below[left - 1]:
        left -= 1
    right = apex
    while right + 1 < len(run) and below[right + 1]:
        right += 1

    if below[left]:
        segment_t = frame_numbers[left : right + 1]
        segment_y = bottoms[left : right + 1]
    else:
        segment_t = frame_numbers
        segment_y = bottoms

    takeoff = int(run[left] if below[left] else run[apex])
    landing = int(run[right] if below[right] else run[apex])

    if len(segment_t) >= 3:
        try:
            a, b, c = np.polyfit(segment_t, segment_y, 2)
            discriminant = b * b - 4.0 * a * (c - baseline)
            if a > 0 and discriminant >= 0:
                root1 = (-b - np.sqrt(discriminant)) / (2.0 * a)
                root2 = (-b + np.sqrt(discriminant)) / (2.0 * a)
                if root1 > root2:
                    root1, root2 = root2, root1
                candidate_takeoff = int(round(root1))
                candidate_landing = int(round(root2))
                low = min(run) - 2
                high = max(run) + 2
                if low <= candidate_takeoff < candidate_landing <= high:
                    takeoff = candidate_takeoff
                    landing = candidate_landing
        except (np.linalg.LinAlgError, ValueError):
            pass

    takeoff = max(0, min(takeoff, len(frames) - 1))
    landing = max(0, min(landing, len(frames) - 1))
    if landing <= takeoff:
        landing = min(len(frames) - 1, takeoff + 1)
    return takeoff, landing


def write_output(path, takeoff, landing):
    try:
        import toml

        with open(path, "w", encoding="utf-8") as handle:
            toml.dump(
                {
                    "jump_takeoff_frame_number": int(takeoff),
                    "jump_land_frame_number": int(landing),
                },
                handle,
            )
    except ImportError:
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(
                "jump_takeoff_frame_number = %d\n" % int(takeoff)
            )
            handle.write(
                "jump_land_frame_number = %d\n" % int(landing)
            )


def main():
    input_path = sys.argv[1] if len(sys.argv) > 1 else "/app/example_video.mp4"
    output_path = sys.argv[2] if len(sys.argv) > 2 else "/app/output.toml"

    frames = read_frames(input_path)
    takeoff, landing = estimate_jump(frames)
    write_output(output_path, takeoff, landing)


if __name__ == "__main__":
    main()
